import { useState, useCallback, KeyboardEvent, ChangeEvent } from 'react';
import { JxInput, JxBadge, JxButton } from '@jinx-ui/react';

interface ArticleTagInputProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  placeholder?: string;
  maxTags?: number;
}

export default function ArticleTagInput({
  value,
  defaultValue = [],
  onChange,
  placeholder = 'Введите тег и нажмите Enter',
  maxTags,
}: ArticleTagInputProps) {
  const isControlled = value !== undefined;
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const tags = isControlled ? (value as string[]) : internalTags;

  const [draft, setDraft] = useState('');

  const commitTags = useCallback(
    (next: string[]) => {
      if (!isControlled) {
        setInternalTags(next);
      }
      onChange?.(next);
    },
    [isControlled, onChange]
  );

  const addTag = useCallback(
    (raw: string) => {
      const trimmed = raw.trim();
      if (!trimmed) return;
      if (tags.includes(trimmed)) return;
      if (maxTags && tags.length >= maxTags) return;
      commitTags([...tags, trimmed]);
    },
    [tags, maxTags, commitTags]
  );

  const removeTag = useCallback(
    (tagToRemove: string) => {
      commitTags(tags.filter((tag) => tag !== tagToRemove));
    },
    [tags, commitTags]
  );

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    const val = event.target.value;
    if (val.endsWith(',')) {
      addTag(val.slice(0, -1));
      setDraft('');
    } else {
      setDraft(val);
    }
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag(draft);
      setDraft('');
    } else if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  const handleBlur = () => {
    if (draft.trim()) {
      addTag(draft);
      setDraft('');
    }
  };

  return (
    <div className="jx-stack jx-stack-gap-sm">
      <JxInput
        value={draft}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        placeholder={placeholder}
        aria-label="Добавить тег статьи"
      />
      {tags.length > 0 && (
        <div className="jx-stack jx-stack-row jx-stack-gap-xs jx-stack-wrap">
          {tags.map((tag) => (
            <JxBadge key={tag} variant="neutral">
              <span>{tag}</span>
              <JxButton
                variant="ghost"
                size="sm"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(tag)}
                style={{ color: 'var(--jx-color-text-muted)' }}
              >
                ×
              </JxButton>
            </JxBadge>
          ))}
        </div>
      )}
    </div>
  );
}

